SET ROLE otr_trip_source_writer;
DO $$
DECLARE actor uuid:='10000000-0000-4000-8000-000000000001';trip uuid:='10000000-0000-4000-8000-000000000002';
 batch uuid:='10000000-0000-4000-8000-000000000003';task uuid:='10000000-0000-4000-8000-000000000004';run uuid:='10000000-0000-4000-8000-000000000005';
 png uuid:='20000000-0000-4000-8000-000000000001';pdf uuid:='20000000-0000-4000-8000-000000000002';txt uuid:='20000000-0000-4000-8000-000000000003';original uuid:='20000000-0000-4000-8000-000000000004';
 stored public.trip_source_inputs;
 submission text:=repeat('a',64);pins jsonb:='[]';approved jsonb;v jsonb;bad jsonb;
BEGIN
 IF has_function_privilege('otr_trip_source_command_gateway','public.trip_source_finite_native_identity(uuid,uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Gateway received direct helper EXEC';END IF;
 INSERT INTO public.trip_source_representations VALUES(png,png,'ORIGINAL',NULL,'image/png'),(pdf,pdf,'DERIVED','otr.pdf.qpdf-poppler','text/plain'),(txt,txt,'ORIGINAL',NULL,'text/plain');
 FOR i IN 1..3 LOOP
  v:=jsonb_build_object('id',CASE i WHEN 1 THEN png WHEN 2 THEN pdf ELSE txt END,'source_id',CASE i WHEN 1 THEN png WHEN 2 THEN pdf ELSE txt END,'representation_id',CASE i WHEN 1 THEN png WHEN 2 THEN pdf ELSE txt END,'material_revision',1,'payload_sha256',repeat(i::text,64),'byte_count',i*10,'observed_source_row_revision',1,'historical_selection',false);
  pins:=pins||jsonb_build_array(v);
 END LOOP;
 approved:=jsonb_set(pins,'{1}',(pins->1)||jsonb_build_object('representation_id',original,'payload_sha256',repeat('4',64),'byte_count',400));
 INSERT INTO public.qa_proofs VALUES(png,actor,trip,'{"proof":"png"}',true),(pdf,actor,trip,jsonb_build_object('pdfSource',jsonb_build_object('original',jsonb_build_object('representationId',original,'sha256',repeat('4',64),'byteCount',400))),true);
 INSERT INTO public.trip_source_universal_scope VALUES(true,actor,trip,batch,task,run,submission,public.trip_import_run_input_hash(approved),clock_timestamp()-interval '1 minute',clock_timestamp()+interval '10 minutes');
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) IS NOT TRUE THEN RAISE EXCEPTION 'valid ABSENT normalized scope rejected';END IF;
 IF EXISTS(SELECT 1 FROM public.trip_source_runs) THEN RAISE EXCEPTION 'guard minted Run';END IF;
 IF public.trip_import_run_input_hash(approved)=public.trip_import_run_input_hash(pins) THEN RAISE EXCEPTION 'fixture hash conflation';END IF;
 IF public.trip_source_finite_native_original_scope(actor,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'DERIVED hash reused as ORIGINAL';END IF;
 IF public.trip_source_finite_native_normalized_scope(trip,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'wrong actor';END IF;
 IF public.trip_source_finite_native_normalized_scope(actor,trip,task,task,run,submission,pins) THEN RAISE EXCEPTION 'wrong batch';END IF;
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,batch,run,submission,pins) THEN RAISE EXCEPTION 'wrong task';END IF;
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,batch,submission,pins) THEN RAISE EXCEPTION 'wrong run';END IF;
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,repeat('b',64),pins) THEN RAISE EXCEPTION 'wrong submission';END IF;
 bad:=jsonb_set(pins,'{0}',(pins->0)||'{"pdfSource":{"fake":true}}');
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,bad) THEN RAISE EXCEPTION 'caller proof accepted';END IF;
 UPDATE public.qa_proofs SET valid=false WHERE id=pdf;
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'missing PDF proof';END IF;
 UPDATE public.qa_proofs SET valid=true,actor='10000000-0000-4000-8000-000000000002'::uuid WHERE id=pdf;
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'wrong Actor PDF proof';END IF;
 UPDATE public.qa_proofs SET actor='10000000-0000-4000-8000-000000000001'::uuid WHERE id=pdf;
 UPDATE public.qa_proofs SET valid=false WHERE id=png;
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'missing PNG proof';END IF;
 UPDATE public.qa_proofs SET valid=true WHERE id=png;
 INSERT INTO public.trip_source_runs(id,actor_account_id,trip_id,capture_batch_id,interpretation_task_id,capture_submission_sha256,extractor_key,state,retention_state,superseded_by) VALUES(run,trip,trip,batch,task,submission,'otr-universal-interpretation-v1','PENDING','RETAINED',NULL);
 IF public.trip_source_finite_native_identity(actor,trip,run) THEN RAISE EXCEPTION 'global wrong-owner Run treated as ABSENT';END IF;
 UPDATE public.trip_source_runs SET actor_account_id=actor,state='FAILED';
 IF public.trip_source_finite_native_identity(actor,trip,run) THEN RAISE EXCEPTION 'failed Run';END IF;
 UPDATE public.trip_source_runs SET state='PENDING',retention_state='REMOVED';
 IF public.trip_source_finite_native_identity(actor,trip,run) THEN RAISE EXCEPTION 'removed Run';END IF;
 UPDATE public.trip_source_runs SET retention_state='RETAINED',superseded_by=task;
 IF public.trip_source_finite_native_identity(actor,trip,run) THEN RAISE EXCEPTION 'superseded Run';END IF;
 UPDATE public.trip_source_runs SET extractor_version='1',operation_key='universal:'||batch::text,extractor_options_sha256=submission,superseded_by=NULL,scope_source_ids=ARRAY[png,pdf],input_sha256=public.trip_import_run_input_hash(pins);
 INSERT INTO public.trip_source_inputs SELECT (jsonb_populate_record(NULL::public.trip_source_inputs,q.v||jsonb_build_object('run_id',run,'confirmation_id',NULL))).* FROM jsonb_array_elements(pins) q(v);
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'wrong stored Source roster';END IF;
 UPDATE public.trip_source_runs SET scope_source_ids=ARRAY(SELECT x FROM unnest(ARRAY[png,pdf,txt]) x ORDER BY x);
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) IS NOT TRUE THEN RAISE EXCEPTION 'valid stored Run rejected';END IF;
 UPDATE public.trip_source_universal_scope SET expires_at=clock_timestamp()-interval '1 second';
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'expired new work';END IF;
 UPDATE public.trip_source_universal_scope SET expires_at=clock_timestamp()+interval '10 minutes',input_sha256=repeat('0',64);
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'wrong approved ORIGINAL hash';END IF;
 SELECT * INTO stored FROM public.trip_source_inputs WHERE id=png AND run_id=run;
 DELETE FROM public.trip_source_universal_scope;
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) IS NOT TRUE THEN RAISE EXCEPTION 'retained read depends on temporary scope';END IF;
 IF public.trip_source_finite_native_normalized_scope(actor,trip,batch,task,run,submission,pins) THEN RAISE EXCEPTION 'closed new work allowed';END IF;
 UPDATE public.trip_source_runs SET capture_batch_id=NULL;
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) THEN RAISE EXCEPTION 'missing Native batch binding';END IF;
 UPDATE public.trip_source_runs SET capture_batch_id=batch,interpretation_task_id=NULL;
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) THEN RAISE EXCEPTION 'missing Task binding';END IF;
 UPDATE public.trip_source_runs SET interpretation_task_id=task,operation_key='foreign';
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) THEN RAISE EXCEPTION 'wrong batch operation key';END IF;
 UPDATE public.trip_source_runs SET operation_key='universal:'||batch::text,extractor_version='2';
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) THEN RAISE EXCEPTION 'wrong extractor version';END IF;
 UPDATE public.trip_source_runs SET extractor_version='1',capture_submission_sha256='bad';
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) THEN RAISE EXCEPTION 'bad submission binding';END IF;
 UPDATE public.trip_source_runs SET capture_submission_sha256=submission,extractor_options_sha256=repeat('b',64);
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) THEN RAISE EXCEPTION 'wrong extractor options binding';END IF;
 UPDATE public.trip_source_runs SET extractor_options_sha256=submission;
 UPDATE public.qa_acl SET allowed=false;
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) THEN RAISE EXCEPTION 'retained read bypassed normal ACL';END IF;
 UPDATE public.qa_acl SET allowed=true;
 stored.representation_id:=pdf;
 IF public.trip_source_finite_native_retained_pin(actor,trip,stored) THEN RAISE EXCEPTION 'retained forged pin accepted';END IF;
 RAISE NOTICE 'FINITE HELPER boundary checks PASS: real PG, synthetic proof/hash dependencies; no full owning proof/retained-read claim';
END $$;
